1	// Builtin tools: voice domain. Exposes the app's own speech stack (the same
2	// ElevenLabs/Deepgram credentials — or the signed-in Rowboat proxy — that
3	// power voice mode) as assistant tools, so agents and Rowboat Apps can
4	// speak and listen without any new API keys.
5	
6	import { z } from "zod";
7	import * as files from "../../../filesystem/files.js";
8	import { BuiltinToolsSchema } from "../types.js";
9	
10	// voice/voice.js reaches di/container (via auth/tokens), which circles back
11	// to the catalog through the agent resolver — import it lazily so this
12	// domain can never trip the cycle regardless of evaluation order (same
13	// lesson as the skills/index ↔ models/defaults cycle).
14	
15	export const MAX_TTS_TEXT_CHARS = 5000;
16	const MAX_TRANSCRIBE_BYTES = 100 * 1024 * 1024;
17	
18	export const voiceTools: z.infer<typeof BuiltinToolsSchema> = {
19	    'text-to-speech': {
20	        permission: "file-boundary",
21	        description: "Convert text to natural spoken audio (the app's own voice stack — no API keys needed) and save it as an .mp3 file. Returns the saved path. Use for narration, audio versions of notes/summaries, or dialogue segments. Pass different ElevenLabs voiceIds across calls to voice different speakers (e.g. a two-host podcast).",
22	        inputSchema: z.object({
23	            text: z.string().min(1).max(MAX_TTS_TEXT_CHARS)
24	                .describe(`The text to speak (max ${MAX_TTS_TEXT_CHARS} chars — synthesize long content one segment per call)`),
25	            outputPath: z.string().optional()
26	                .describe("Where to save the .mp3 (workspace-relative or absolute). Default: media/tts/tts-<timestamp>.mp3"),
27	            voiceId: z.string().optional()
28	                .describe("ElevenLabs voice id (e.g. pNInz6obpgDQGcFmaJgB male, 21m00Tcm4TlvDq8ikWAM female). Omit for the app's default voice."),
29	        }),
30	        execute: async ({ text, outputPath, voiceId }: { text: string; outputPath?: string; voiceId?: string }) => {
31	            try {
32	                const { synthesizeSpeech } = await import("../../../voice/voice.js");
33	                // Produced artifact → quality tier (voice mode keeps flash).
34	                const { audioBase64, mimeType } = await synthesizeSpeech(text, { voiceId, modelId: 'eleven_turbo_v2_5' });
35	                const buffer = Buffer.from(audioBase64, 'base64');
36	                const target = outputPath
37	                    || `media/tts/tts-${new Date().toISOString().replace(/[:.]/g, '-')}.mp3`;
38	                const result = await files.writeBuffer(target, buffer);
39	                return { success: true, path: result.path, resolvedPath: result.resolvedPath, mimeType, bytes: buffer.length };
40	            } catch (e) {
41	                return { success: false, error: e instanceof Error ? e.message : String(e) };
42	            }
43	        },
44	    },
45	    'transcribe-audio': {
46	        permission: "file-boundary",
47	        description: "Transcribe an audio file to text using the app's speech-to-text (same credentials as voice mode — no API keys needed). Handles common formats (wav, mp3, ogg/opus, webm). Use for voice memos, recordings, or audio produced by text-to-speech.",
48	        inputSchema: z.object({
49	            path: z.string().describe("The audio file to transcribe (workspace-relative or absolute)"),
50	        }),
51	        execute: async ({ path: inputPath }: { path: string }) => {
52	            try {
53	                const { buffer, path: originalPath } = await files.readBuffer(inputPath);
54	                if (buffer.length === 0) return { success: false, error: `File is empty: ${inputPath}` };
55	                if (buffer.length > MAX_TRANSCRIBE_BYTES) {
56	                    return { success: false, error: `File exceeds ${MAX_TRANSCRIBE_BYTES / (1024 * 1024)} MB: ${inputPath}` };
57	                }
58	                const { transcribeAudio } = await import("../../../voice/voice.js");
59	                const { transcript } = await transcribeAudio(buffer);
60	                return { success: true, path: originalPath, transcript };
61	            } catch (e) {
62	                return { success: false, error: e instanceof Error ? e.message : String(e) };
63	            }
64	        },
65	    },
66	};
